raw_current_date = current_date_and_time["date"].strip()
month_numbers = {name: index + 1 for index, name in enumerate(["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"])}
if len(raw_current_date) >= 10 and raw_current_date[4] == "-" and raw_current_date[7] == "-":
    current_year, current_month, current_day = [int(piece) for piece in raw_current_date[:10].split("-")]
elif "/" in raw_current_date:
    date_pieces = raw_current_date.split("/")
    if len(date_pieces[0]) == 4:
        current_year, current_month, current_day = [int(piece) for piece in date_pieces]
    else:
        current_month, current_day, current_year = [int(piece) for piece in date_pieces]
else:
    date_words = raw_current_date.replace(",", "").split()
    month_position = next(index for index, word in enumerate(date_words) if word.lower() in month_numbers)
    current_month = month_numbers[date_words[month_position].lower()]
    day_word = date_words[month_position + 1].lower()
    for suffix in ("st", "nd", "rd", "th"):
        if day_word.endswith(suffix):
            day_word = day_word[:-2]
            break
    current_day = int(day_word)
    current_year = int(date_words[month_position + 2])
window_max_created_at = f"{current_year:04d}-{current_month:02d}-{current_day:02d}"
window_year, window_month, window_day = current_year, current_month, current_day
for _ in range(9):
    window_day -= 1
    if window_day == 0:
        window_month -= 1
        if window_month == 0:
            window_month = 12
            window_year -= 1
        leap_year = window_year % 4 == 0 and (window_year % 100 != 0 or window_year % 400 == 0)
        month_lengths = [31, 29 if leap_year else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        window_day = month_lengths[window_month - 1]
window_min_created_at = f"{window_year:04d}-{window_month:02d}-{window_day:02d}"
